#include <iostream>
#include <vector>
using namespace std;

int findBitonicPoint(vector<int>& nums) {
  // 左索引的初始值为 0
  int left = 0;
  // # 右索引的初始值是数组中元素的数量
  int right = nums.size();
  // # left + 1 >= right 将完成while循环
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid - 1] < nums[mid] && nums[mid + 1] < nums[mid]) {
      // mid 是要回答的索引
      return mid;
    } else if (nums[mid - 1] < nums[mid]) {
      // 在数组的左半部分搜索是没有意义的
      left = mid;
    } else {
      // 在数组的右半部分搜索没有意义
      right = mid;
    }
  }
  // 左边是答案
  return left;
}

int main() {
  vector<int> nums1 = {-8, 1, 2, 3, 4, 5, -2, -3, -9};
  vector<int> nums2 = {1, 2, 3, 4, 5, 6, 7, 8, 9, 0};
  vector<int> nums3 = {0, 9, 8, 7, 6, 5, 4, 3, 2, 1};

  cout << "The peak index is ---> " << findBitonicPoint(nums1) << endl;
  cout << "The peak index is ---> " << findBitonicPoint(nums2) << endl;
  cout << "The peak index is ---> " << findBitonicPoint(nums3) << endl;

  return 0;
}

class Solution {
  int findBitonicPoint(int[] nums) {
    // 左索引的初始值为 0
    int left = 0;
    // # 右索引的初始值是数组中元素的数量
    int right = nums.length;
    // # left + 1 >= right 将完成while循环
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid - 1] < nums[mid] && nums[mid + 1] < nums[mid]) {
        // mid 是要回答的索引
        return mid;
      } else if (nums[mid - 1] < nums[mid]) {
        // 在数组的左半部分搜索是没有意义的
        left = mid;
      } else {
        // 在数组的右半部分搜索没有意义
        right = mid;
      }
    }
    // 左边是答案
    return left;
  }

  public static void main(String[] args) {
    Solution sol = new Solution();
    int[] nums1 = new int[] {-8, 1, 2, 3, 4, 5, -2, -3, -9};
    int[] nums2 = new int[] {1, 2, 3, 4, 5, 6, 7, 8, 9, 0};
    int[] nums3 = new int[] {0, 9, 8, 7, 6, 5, 4, 3, 2, 1};

    System.out.println("The peak index is ---> " + sol.findBitonicPoint(nums1));
    System.out.println("The peak index is ---> " + sol.findBitonicPoint(nums2));
    System.out.println("The peak index is ---> " + sol.findBitonicPoint(nums3));
  }
}

const findBitonicPoint = function(nums) {
